<script lang="ts">
 import {base} from '$app/paths';
 import SoulTile,{type SoulColor} from './SoulTile.svelte';
 import DivineFavor from './DivineFavor.svelte';
 import SacredRegion from './SacredRegion.svelte';
 import SharedHeaven from './SharedHeaven.svelte';
 import SuitSymbol from './SuitSymbol.svelte';
 const colors: SoulColor[]=['black','red','blue','green'];
 const names=['Zadkiel','Raphael','Selaphiel','Barachiel'];
 let inspectorOpen=$state(false),resetKey=$state(0);
 let color=$state<SoulColor>('blue'),rank=$state<number|'joker'>(7),tileSize=$state(64);
 let showBody=$state(true),showFace=$state(true),showState=$state(true),exploded=$state(false);
 let favors=$state([5,5,2,0]),active=$state(0),sanctuary=$state<'four'|'three'>('four'),rescued=$state(false),choirAvailable=$state(true),processionAvailable=$state(true),purgatoryAvailable=$state(true);
 const allowances=$derived(favors.map((value,i)=>favors.length-favors.filter((other,j)=>j!==i&&other>=value).length));
 function reset(){resetKey++;sanctuary='four';rescued=false;favors=[5,5,2,0];active=0;choirAvailable=true;processionAvailable=true;purgatoryAvailable=true;}
</script>
<div class="digital-collection">
 <div class="table-tools"><a href={`${base}/gallery`} aria-label="Back to component gallery" title="Component gallery">←</a><button aria-label="Toggle component review controls" aria-expanded={inspectorOpen} title="Review controls" onclick={()=>inspectorOpen=!inspectorOpen}>⚙</button></div>
 <SharedHeaven moved={sanctuary==='three'} {rescued} {resetKey}/>
 <div class="table-counters" aria-label="Divine Favor">{#each favors as value,i}<DivineFavor {value} name={names[i]}/>{/each}</div>
  <div class="regions-grid">
   <SacredRegion owner="Selaphiel" title="Sanctuary of Choirs" available={choirAvailable}>{#each (sanctuary==='four'?colors:colors.slice(0,3)) as c}<SoulTile rank={7} color={c} size={52}/>{/each}</SacredRegion>
   <SacredRegion owner="Barachiel" title="Sanctuary of Processions" available={processionAvailable}>{#each [9,10,11] as n}<SoulTile rank={n} color="green" size={56}/>{/each}</SacredRegion>
   <SacredRegion kind="purgatory" owner="Raphael" title="Purgatory" available={purgatoryAvailable}>{#if !rescued}<SoulTile rank={9} color="blue" size={58}/>{/if}</SacredRegion>
  </div>
 <div class="review-inspector" hidden={!inspectorOpen}>
 <div class="table-preview-controls"><button onclick={reset}>Refill play area</button><p>Ordinary Choir and Procession rules apply. Jokers fill legal missing positions. Click or drag a soul to split before it. Double-click or double-tap to select the whole group for dragging. Click blank Heaven to clear group selection. Drop beside or between another group’s souls to join. Matching rows snap north/south; select a stack and press T or the transpose icon to regroup its columns. ⌘/Ctrl Z undoes a rearrangement.</p></div>

 <header class="digital-intro"><div><p class="eyebrow">THE DIGITAL TABLE · COMPONENT STUDIES</p><h2>A shared Heaven.</h2><p>Four suits in ivory and enamel, gilded Favor, and room for every formation. Explore the table, change the states, and lift the layers apart.</p></div><span class="study-seal">01<span>ART DIRECTION</span></span></header>
 <div class="object-studies">
  <section class="tile-hero" aria-label="Soul tile art study"><div class="study-heading"><p class="eyebrow">01 / SOULS</p><h3>A small soul.<br/>A substantial presence.</h3><p>Warm ivory, a fine gold inlay, and colored enamel markings.</p></div><div class="hero-tiles">{#each colors as c,i}<div style={`--lean:${(i-1.5)*5}deg;--raise:${Math.abs(i-1.5)*8}px`}><SoulTile rank={i===1?12:7} color={c} size={88}/></div>{/each}<div style="--lean:12deg;--raise:16px"><SoulTile rank="joker" size={88}/></div></div><p class="hero-caption">Four suits. Thirteen ranks. Two wild souls.</p></section>
  <section class="favor-study" aria-label="Divine Favor art study"><p class="eyebrow">02 / DIVINE FAVOR</p><h3>Grace has its rewards.</h3><p class="study-copy">More Favor gives you more choice when drawing. Keep one soul.</p><div class="favor-players">{#each favors as value,i}<button class:active={active===i} aria-pressed={active===i} aria-label={`Select ${names[i]}’s Favor`} onclick={()=>active=i}><DivineFavor {value} allowance={allowances[i]} name={names[i]}/><span>{names[i]}</span></button>{/each}</div><div class="favor-adjust"><span>{names[active]}’s Favor</span><button aria-label="Decrease sample Favor" disabled={favors[active]===0} onclick={()=>favors[active]=Math.max(0,favors[active]-1)}>−</button><output aria-label="Sample Favor">{favors[active]}</output><button aria-label="Increase sample Favor" onclick={()=>favors[active]++}>+</button></div><p class="favor-explanation">With four players, a sole leader inspects four souls. Tied players receive the lower allowance. Everyone keeps just one.</p></section>
 </div>
 <section class="table-study" aria-labelledby="regions-heading"><div class="section-heading"><div><p class="eyebrow">03 / SPECIAL AREAS</p><h3 id="regions-heading">A place when you need it.</h3></div><button class="quiet-button" onclick={reset}>Reset table study</button></div><p class="section-copy">Available Sanctuaries protect the souls inside their boundaries. Raphael’s Purgatory holds one soul until its rescue.</p>
  <fieldset class="area-availability"><legend>Available areas</legend><label><input type="checkbox" bind:checked={choirAvailable}/>Choir Sanctuary</label><label><input type="checkbox" bind:checked={processionAvailable}/>Procession Sanctuary</label><label><input type="checkbox" bind:checked={purgatoryAvailable}/>Purgatory</label></fieldset>

  <div class="region-controls">{#if choirAvailable}<div class="state-options" aria-label="Choir Sanctuary state">{#each [['four','Four protected'],['three','Move the fourth']] as [value,label]}<button aria-pressed={sanctuary===value} onclick={()=>sanctuary=value as typeof sanctuary}>{label}</button>{/each}</div>{/if}{#if purgatoryAvailable}<button class="rescue-button" onclick={()=>rescued=!rescued}>{rescued?'Return to waiting state':'Rescue into Procession'} <span aria-hidden="true">↗</span></button>{/if}</div>
  <p class="scenario-note" aria-live="polite">{#if choirAvailable}{sanctuary==='three'?'Three souls remain protected; the green 7 is now public.':'All four souls inside Selaphiel’s Sanctuary are protected.'}{/if} {#if purgatoryAvailable}{rescued?'Raphael’s blue 9 has joined a legal Procession.':'Purgatory may remain occupied when Raphael goes out.'}{/if}</p>
 </section>
 <section class="layer-study" aria-labelledby="layers-heading"><div class="layer-specimen"><div class="specimen-grid"><SoulTile {rank} {color} size={144} selected body={showBody} face={showFace} states={showState} {exploded}/></div><p>{exploded?'Layers separated':'The assembled soul'}</p></div><div class="layer-controls"><p class="eyebrow">04 / LAYER COMPOSITION</p><h3 id="layers-heading">Made to move.<br/>Made to stay readable.</h3><p>The painted body and the live markings are independent. Ranks, colors, and selection can change without replacing the illustration.</p><fieldset><legend>Visible layers</legend><label><input type="checkbox" bind:checked={showBody}/><span><b>01 · Painted ivory</b><small>Transparent ceramic body, bevel and gold inlay.</small></span></label><label><input type="checkbox" bind:checked={showFace}/><span><b>02 · Live enamel</b><small>Rank and color symbol, or the wild-soul mark.</small></span></label><label><input type="checkbox" bind:checked={showState}/><span><b>03 · Selection</b><small>Independent outline and check mark.</small></span></label></fieldset><button class="explode-button" aria-pressed={exploded} onclick={()=>exploded=!exploded}>{exploded?'Reassemble the tile':'Separate the layers'} <span aria-hidden="true">↗</span></button></div></section>
 <section class="tile-catalog" aria-labelledby="ranks-heading"><div class="section-heading"><div><p class="eyebrow">05 / THE FULL SET</p><h3 id="ranks-heading">Every rank. Every suit.</h3></div><label class="size-control">Tile size <input type="range" min="42" max="84" step="2" bind:value={tileSize} aria-label="Tile display size"/><output>{tileSize}px</output></label></div><div class="palette" aria-label="Soul suit">{#each colors as c}<button class="color-choice" data-color={c} aria-pressed={color===c} onclick={()=>color=c}><span><SuitSymbol color={c}/></span>{c==='black'?'Spades':c==='red'?'Hearts':c==='blue'?'Diamonds':'Clubs'}</button>{/each}</div><div class="rank-collection">{#each Array.from({length:13},(_,i)=>i+1) as n}<button class="tile-choice" class:picked={rank===n} aria-pressed={rank===n} aria-label={`Inspect ${color} ${n}`} onclick={()=>rank=n}><SoulTile rank={n} {color} size={tileSize}/></button>{/each}<button class="tile-choice" class:picked={rank==='joker'} aria-pressed={rank==='joker'} aria-label="Inspect joker" onclick={()=>rank='joker'}><SoulTile rank="joker" size={tileSize}/></button><div class="back-example"><SoulTile back size={tileSize}/><span>Private hand</span></div></div><p class="catalog-note">Select a soul to preview its layers above. Black spades, red hearts, blue diamonds, and green clubs. The tile back reveals neither rank nor color.</p></section>
 <div class="digital-production-note"><span>PAINTED ART · LIVE STATE</span><p>Four original paintings. Reusable components. No numbers, tiles, or rules baked into the region artwork.</p></div>
 </div>
</div>
